cat > src/main.rs <<'EOF'
use std::process::ExitCode;

use wgpu::util::DeviceExt;

const WORKGROUP: u32 = 16;

const SHADER: &str = r#"
struct Dims {
    width: u32,
    height: u32,
}

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16, 1)
fn step(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= dims.width || y >= dims.height) {
        return;
    }
    let w = dims.width;
    let xl = select(x - 1u, x, x == 0u);
    let xr = min(x + 1u, w - 1u);
    let yu = select(y - 1u, y, y == 0u);
    let yd = min(y + 1u, dims.height - 1u);
    let c = src[y * w + x];
    let sum = 4u * c + src[y * w + xl] + src[y * w + xr] + src[yu * w + x] + src[yd * w + x];
    dst[y * w + x] = sum / 8u;
}
"#;

struct Grid {
    width: u32,
    height: u32,
    steps: u32,
    cells: Vec<u32>,
}

fn parse(text: &str) -> Result<Grid, String> {
    let mut tokens = text.split_ascii_whitespace();
    let mut next = |what: &str| -> Result<u64, String> {
        let tok = tokens.next().ok_or_else(|| format!("missing {what}"))?;
        tok.parse::<u64>()
            .map_err(|_| format!("invalid {what}: {tok:?}"))
    };
    let width = next("width")?;
    let height = next("height")?;
    let steps = next("steps")?;
    if !(1..=512).contains(&width) {
        return Err(format!("width {width} out of range 1..=512"));
    }
    if !(1..=512).contains(&height) {
        return Err(format!("height {height} out of range 1..=512"));
    }
    if steps > 1000 {
        return Err(format!("steps {steps} out of range 0..=1000"));
    }
    let n = (width * height) as usize;
    let mut cells = Vec::with_capacity(n);
    for i in 0..n {
        let v = next(&format!("cell {i}"))?;
        if v > 1_000_000 {
            return Err(format!("cell {i} value {v} out of range 0..=1000000"));
        }
        cells.push(v as u32);
    }
    if tokens.next().is_some() {
        return Err("unexpected extra data after grid".to_string());
    }
    Ok(Grid {
        width: width as u32,
        height: height as u32,
        steps: steps as u32,
        cells,
    })
}

async fn run_gpu(grid: &Grid) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(&wgpu::InstanceDescriptor::default());
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            ..Default::default()
        })
        .await
        .ok_or("no GPU adapter available")?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default(), None)
        .await
        .map_err(|e| format!("failed to create GPU device: {e}"))?;

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("heat"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat"),
        layout: None,
        module: &module,
        entry_point: Some("step"),
        compilation_options: Default::default(),
        cache: None,
    });

    let bytes = (grid.cells.len() * std::mem::size_of::<u32>()) as u64;
    let dims = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("dims"),
        contents: bytemuck::cast_slice(&[grid.width, grid.height]),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let storage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC;
    let buffers = [
        device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("grid a"),
            contents: bytemuck::cast_slice(&grid.cells),
            usage: storage,
        }),
        device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("grid b"),
            size: bytes,
            usage: storage,
            mapped_at_creation: false,
        }),
    ];
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: bytes,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let layout = pipeline.get_bind_group_layout(0);
    // bind_groups[i] reads buffers[i] and writes buffers[1 - i].
    let bind_groups: Vec<wgpu::BindGroup> = (0..2)
        .map(|i| {
            device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: Some("heat"),
                layout: &layout,
                entries: &[
                    wgpu::BindGroupEntry {
                        binding: 0,
                        resource: dims.as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 1,
                        resource: buffers[i].as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 2,
                        resource: buffers[1 - i].as_entire_binding(),
                    },
                ],
            })
        })
        .collect();

    let groups_x = grid.width.div_ceil(WORKGROUP);
    let groups_y = grid.height.div_ceil(WORKGROUP);
    let mut encoder = device.create_command_encoder(&Default::default());
    for s in 0..grid.steps as usize {
        // Separate passes so each step sees the previous step's complete output.
        let mut pass = encoder.begin_compute_pass(&Default::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_groups[s % 2], &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }
    let result = &buffers[grid.steps as usize % 2];
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, bytes);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device.poll(wgpu::Maintain::Wait);
    rx.recv()
        .map_err(|e| format!("readback channel failed: {e}"))?
        .map_err(|e| format!("failed to map readback buffer: {e}"))?;
    let out = bytemuck::cast_slice::<u8, u32>(&slice.get_mapped_range()).to_vec();
    readback.unmap();
    Ok(out)
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: gpu-heat <input-file>");
        return ExitCode::FAILURE;
    };
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {path}: {e}");
            return ExitCode::FAILURE;
        }
    };
    let grid = match parse(&text) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("bad input: {e}");
            return ExitCode::FAILURE;
        }
    };
    let cells = match pollster::block_on(run_gpu(&grid)) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("GPU error: {e}");
            return ExitCode::FAILURE;
        }
    };

    let mut out = String::with_capacity(cells.len() * 8);
    for row in cells.chunks(grid.width as usize) {
        let line: Vec<String> = row.iter().map(u32::to_string).collect();
        out.push_str(&line.join(" "));
        out.push('\n');
    }
    let total: u64 = cells.iter().map(|&v| u64::from(v)).sum();
    out.push_str(&format!("SUM {total}\n"));

    use std::io::Write;
    let mut stdout = std::io::stdout().lock();
    if let Err(e) = stdout.write_all(out.as_bytes()).and_then(|_| stdout.flush()) {
        eprintln!("write failed: {e}");
        return ExitCode::FAILURE;
    }
    ExitCode::SUCCESS
}
EOF
